import { readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'

// Generated by scripts/social-preview.mjs (node scripts/social-preview.mjs); uploaded manually in GitHub Settings -> General.
const path = join(__dirname, '..', 'docs', 'images', 'readme', 'social-preview.png')

describe('social preview image', () => {
  it('is 1280x640 and under 1 MB', () => {
    expect(statSync(path).size).toBeLessThan(1024 * 1024)
    const png = readFileSync(path)
    expect(png.subarray(1, 4).toString('latin1')).toBe('PNG')
    expect(png.readUInt32BE(16)).toBe(1280)
    expect(png.readUInt32BE(20)).toBe(640)
  })
})
